14	TableNamesSet getDependenciesSetFromCreateQuery(ContextPtr global_context, const QualifiedTableName & table, const ASTPtr & ast)
15	{
16	    assert(global_context == global_context->getGlobalContext());
17	    TableLoadingDependenciesVisitor::Data data;
18	    data.default_database = global_context->getCurrentDatabase();
19	    data.create_query = ast;
20	    data.global_context = global_context;
21	    TableLoadingDependenciesVisitor visitor{data};
22	    visitor.visit(ast);
23	    data.dependencies.erase(table);
24	    return data.dependencies;
25	}
