27	void DDLDependencyVisitor::visit(const ASTPtr & ast, Data & data)
28	{
29	    /// Looking for functions in column default expressions and dictionary source definition
30	    if (const auto * function = ast->as<ASTFunction>())
31	        visit(*function, data);
32	    else if (const auto * dict_source = ast->as<ASTFunctionWithKeyValueArguments>())
33	        visit(*dict_source, data);
34	    else if (const auto * storage = ast->as<ASTStorage>())
35	        visit(*storage, data);
36	}
