38	bool DDLDependencyVisitor::needChildVisit(const ASTPtr & node, const ASTPtr & child)
39	{
40	    if (node->as<ASTStorage>())
41	        return false;
42	
43	    if (auto * create = node->as<ASTCreateQuery>())
44	    {
45	        if (child.get() == create->select)
46	            return false;
47	    }
48	
49	    return true;
50	}
