52	void DDLDependencyVisitor::visit(const ASTFunction & function, Data & data)
53	{
54	    if (function.name == "joinGet" ||
55	        function.name == "dictHas" ||
56	        function.name == "dictIsIn" ||
57	        function.name.starts_with("dictGet"))
58	    {
59	        extractTableNameFromArgument(function, data, 0);
60	    }
61	    else if (Poco::toLower(function.name) == "in")
62	    {
63	        extractTableNameFromArgument(function, data, 1);
64	    }
65	
66	}
