68	void DDLDependencyVisitor::visit(const ASTFunctionWithKeyValueArguments & dict_source, Data & data)
69	{
70	    if (dict_source.name != "clickhouse")
71	        return;
72	    if (!dict_source.elements)
73	        return;
74	
75	    auto config = getDictionaryConfigurationFromAST(data.create_query->as<ASTCreateQuery &>(), data.global_context);
76	    auto info = getInfoIfClickHouseDictionarySource(config, data.global_context);
77	
78	    if (!info || !info->is_local)
79	        return;
80	
81	    if (info->table_name.database.empty())
82	        info->table_name.database = data.default_database;
83	    data.dependencies.emplace(std::move(info->table_name));
84	}
