86	void DDLDependencyVisitor::visit(const ASTStorage & storage, Data & data)
87	{
88	    if (!storage.engine)
89	        return;
90	    if (storage.engine->name != "Dictionary")
91	        return;
92	
93	    extractTableNameFromArgument(*storage.engine, data, 0);
94	}
