97	void DDLDependencyVisitor::extractTableNameFromArgument(const ASTFunction & function, Data & data, size_t arg_idx)
98	{
99	    /// Just ignore incorrect arguments, proper exception will be thrown later
100	    if (!function.arguments || function.arguments->children.size() <= arg_idx)
101	        return;
102	
103	    QualifiedTableName qualified_name;
104	
105	    const auto * arg = function.arguments->as<ASTExpressionList>()->children[arg_idx].get();
106	    if (const auto * literal = arg->as<ASTLiteral>())
107	    {
108	        if (literal->value.getType() != Field::Types::String)
109	            return;
110	
111	        auto maybe_qualified_name = QualifiedTableName::tryParseFromString(literal->value.get<String>());
112	        /// Just return if name if invalid
113	        if (!maybe_qualified_name)
114	            return;
115	
116	        qualified_name = std::move(*maybe_qualified_name);
117	    }
118	    else if (const auto * identifier = dynamic_cast<const ASTIdentifier *>(arg))
119	    {
120	        /// ASTIdentifier or ASTTableIdentifier
121	        auto table_identifier = identifier->createTable();
122	        /// Just return if table identified is invalid
123	        if (!table_identifier)
124	            return;
125	
126	        qualified_name.database = table_identifier->getDatabaseName();
127	        qualified_name.table = table_identifier->shortName();
128	    }
129	    else
130	    {
131	        assert(false);
132	        return;
133	    }
134	
135	    if (qualified_name.database.empty())
136	    {
137	        /// It can be table/dictionary from default database or XML dictionary, but we cannot distinguish it here.
138	        qualified_name.database = data.default_database;
139	    }
140	    data.dependencies.emplace(std::move(qualified_name));
141	}
142	
143	}
