112	RestorerFromBackup::DataRestoreTasks RestorerFromBackup::run(Mode mode)
113	{
114	    /// run() can be called onle once.
115	    if (!current_status.empty())
116	        throw Exception(ErrorCodes::LOGICAL_ERROR, "Already restoring");
117	
118	    /// Find other hosts working along with us to execute this ON CLUSTER query.
119	    all_hosts = BackupSettings::Util::filterHostIDs(
120	        restore_settings.cluster_host_ids, restore_settings.shard_num, restore_settings.replica_num);
121	
122	    /// Do renaming in the create queries according to the renaming config.
123	    renaming_map = makeRenamingMapFromBackupQuery(restore_query_elements);
124	
125	    /// Calculate the root path in the backup for restoring, it's either empty or has the format "shards/<shard_num>/replicas/<replica_num>/".
126	    findRootPathsInBackup();
127	
128	    /// Find all the databases and tables which we will read from the backup.
129	    setStatus(kFindingTablesInBackupStatus);
130	    findDatabasesAndTablesInBackup();
131	
132	    /// Check access rights.
133	    checkAccessForObjectsFoundInBackup();
134	
135	    if (mode == Mode::CHECK_ACCESS_ONLY)
136	        return {};
137	
138	    /// Create databases using the create queries read from the backup.
139	    setStatus(kCreatingDatabasesStatus);
140	    createDatabases();
141	
142	    /// Create tables using the create queries read from the backup.
143	    setStatus(kCreatingTablesStatus);
144	    createTables();
145	
146	    /// All what's left is to insert data to tables.
147	    /// No more data restoring tasks are allowed after this point.
148	    setStatus(kInsertingDataToTablesStatus);
149	    return getDataRestoreTasks();
150	}
