163	void RestorerFromBackup::findRootPathsInBackup()
164	{
165	    size_t shard_num = 1;
166	    size_t replica_num = 1;
167	    if (!restore_settings.host_id.empty())
168	    {
169	        std::tie(shard_num, replica_num)
170	            = BackupSettings::Util::findShardNumAndReplicaNum(restore_settings.cluster_host_ids, restore_settings.host_id);
171	    }
172	
173	    root_paths_in_backup.clear();
174	
175	    /// Start with "" as the root path and then we will add shard- and replica-related part to it.
176	    fs::path root_path = "/";
177	    root_paths_in_backup.push_back(root_path);
178	
179	    /// Add shard-related part to the root path.
180	    Strings shards_in_backup = backup->listFiles(root_path / "shards");
181	    if (shards_in_backup.empty())
182	    {
183	        if (restore_settings.shard_num_in_backup > 1)
184	            throw Exception(ErrorCodes::BACKUP_ENTRY_NOT_FOUND, "No shard #{} in backup", restore_settings.shard_num_in_backup);
185	    }
186	    else
187	    {
188	        String shard_name;
189	        if (restore_settings.shard_num_in_backup)
190	            shard_name = std::to_string(restore_settings.shard_num_in_backup);
191	        else if (shards_in_backup.size() == 1)
192	            shard_name = shards_in_backup.front();
193	        else
194	            shard_name = std::to_string(shard_num);
195	        if (std::find(shards_in_backup.begin(), shards_in_backup.end(), shard_name) == shards_in_backup.end())
196	            throw Exception(ErrorCodes::BACKUP_ENTRY_NOT_FOUND, "No shard #{} in backup", shard_name);
197	        root_path = root_path / "shards" / shard_name;
198	        root_paths_in_backup.push_back(root_path);
199	    }
200	
201	    /// Add replica-related part to the root path.
202	    Strings replicas_in_backup = backup->listFiles(root_path / "replicas");
203	    if (replicas_in_backup.empty())
204	    {
205	        if (restore_settings.replica_num_in_backup > 1)
206	            throw Exception(ErrorCodes::BACKUP_ENTRY_NOT_FOUND, "No replica #{} in backup", restore_settings.replica_num_in_backup);
207	    }
208	    else
209	    {
210	        String replica_name;
211	        if (restore_settings.replica_num_in_backup)
212	        {
213	            replica_name = std::to_string(restore_settings.replica_num_in_backup);
214	            if (std::find(replicas_in_backup.begin(), replicas_in_backup.end(), replica_name) == replicas_in_backup.end())
215	                throw Exception(ErrorCodes::BACKUP_ENTRY_NOT_FOUND, "No replica #{} in backup", replica_name);
216	        }
217	        else
218	        {
219	            replica_name = std::to_string(replica_num);
220	            if (std::find(replicas_in_backup.begin(), replicas_in_backup.end(), replica_name) == replicas_in_backup.end())
221	                replica_name = replicas_in_backup.front();
222	        }
223	        root_path = root_path / "replicas" / replica_name;
224	        root_paths_in_backup.push_back(root_path);
225	    }
226	
227	    /// Revert the list of root paths, because we need it in the following order:
228	    /// "/shards/<shard_num>/replicas/<replica_num>/" (first we search tables here)
229	    /// "/shards/<shard_num>/" (then here)
230	    /// "/" (and finally here)
231	    std::reverse(root_paths_in_backup.begin(), root_paths_in_backup.end());
232	
233	    LOG_TRACE(
234	        log,
235	        "Will use paths in backup: {}",
236	        boost::algorithm::join(
237	            root_paths_in_backup
238	                | boost::adaptors::transformed([](const fs::path & path) -> String { return doubleQuoteString(String{path}); }),
239	            ", "));
240	}
