242	void RestorerFromBackup::findDatabasesAndTablesInBackup()
243	{
244	    database_infos.clear();
245	    table_infos.clear();
246	    for (const auto & element : restore_query_elements)
247	    {
248	        switch (element.type)
249	        {
250	            case ASTBackupQuery::ElementType::TABLE:
251	            {
252	                findTableInBackup({element.database_name, element.table_name}, element.partitions);
253	                break;
254	            }
255	            case ASTBackupQuery::ElementType::TEMPORARY_TABLE:
256	            {
257	                findTableInBackup({DatabaseCatalog::TEMPORARY_DATABASE, element.table_name}, element.partitions);
258	                break;
259	            }
260	            case ASTBackupQuery::ElementType::DATABASE:
261	            {
262	                findDatabaseInBackup(element.database_name, element.except_tables);
263	                break;
264	            }
265	            case ASTBackupQuery::ElementType::ALL:
266	            {
267	                findEverythingInBackup(element.except_databases, element.except_tables);
268	                break;
269	            }
270	        }
271	    }
272	
273	    LOG_INFO(log, "Will restore {} databases and {} tables", database_infos.size(), table_infos.size());
274	}
