276	void RestorerFromBackup::findTableInBackup(const QualifiedTableName & table_name_in_backup, const std::optional<ASTs> & partitions)
277	{
278	    bool is_temporary_table = (table_name_in_backup.database == DatabaseCatalog::TEMPORARY_DATABASE);
279	
280	    std::optional<fs::path> metadata_path;
281	    std::optional<fs::path> root_path_in_use;
282	    for (const auto & root_path_in_backup : root_paths_in_backup)
283	    {
284	        fs::path try_metadata_path;
285	        if (is_temporary_table)
286	        {
287	            try_metadata_path
288	                = root_path_in_backup / "temporary_tables" / "metadata" / (escapeForFileName(table_name_in_backup.table) + ".sql");
289	        }
290	        else
291	        {
292	            try_metadata_path = root_path_in_backup / "metadata" / escapeForFileName(table_name_in_backup.database)
293	                / (escapeForFileName(table_name_in_backup.table) + ".sql");
294	        }
295	
296	        if (backup->fileExists(try_metadata_path))
297	        {
298	            metadata_path = try_metadata_path;
299	            root_path_in_use = root_path_in_backup;
300	            break;
301	        }
302	    }
303	
304	    if (!metadata_path)
305	        throw Exception(
306	            ErrorCodes::BACKUP_ENTRY_NOT_FOUND,
307	            "{} not found in backup",
308	            tableNameWithTypeToString(table_name_in_backup.database, table_name_in_backup.table, true));
309	
310	    fs::path data_path_in_backup;
311	    if (is_temporary_table)
312	    {
313	        data_path_in_backup = *root_path_in_use / "temporary_tables" / "data" / escapeForFileName(table_name_in_backup.table);
314	    }
315	    else
316	    {
317	        data_path_in_backup
318	            = *root_path_in_use / "data" / escapeForFileName(table_name_in_backup.database) / escapeForFileName(table_name_in_backup.table);
319	    }
320	
321	    auto read_buffer = backup->readFile(*metadata_path)->getReadBuffer();
322	    String create_query_str;
323	    readStringUntilEOF(create_query_str, *read_buffer);
324	    read_buffer.reset();
325	    ParserCreateQuery create_parser;
326	    ASTPtr create_table_query = parseQuery(create_parser, create_query_str, 0, DBMS_DEFAULT_MAX_PARSER_DEPTH);
327	    renameDatabaseAndTableNameInCreateQuery(create_table_query, renaming_map, context->getGlobalContext());
328	
329	    QualifiedTableName table_name = renaming_map.getNewTableName(table_name_in_backup);
330	
331	    if (auto it = table_infos.find(table_name); it != table_infos.end())
332	    {
333	        const TableInfo & table_info = it->second;
334	        if (table_info.create_table_query && (serializeAST(*table_info.create_table_query) != serializeAST(*create_table_query)))
335	        {
336	            throw Exception(
337	                ErrorCodes::CANNOT_RESTORE_TABLE,
338	                "Extracted two different create queries for the same {}: {} and {}",
339	                tableNameWithTypeToString(table_name.database, table_name.table, false),
340	                serializeAST(*table_info.create_table_query),
341	                serializeAST(*create_table_query));
342	        }
343	    }
344	
345	    TableInfo & res_table_info = table_infos[table_name];
346	    res_table_info.create_table_query = create_table_query;
347	    res_table_info.is_predefined_table = DatabaseCatalog::instance().isPredefinedTable(StorageID{table_name.database, table_name.table});
348	    res_table_info.dependencies = getDependenciesSetFromCreateQuery(context->getGlobalContext(), table_name, create_table_query);
349	    res_table_info.has_data = backup->hasFiles(data_path_in_backup);
350	    res_table_info.data_path_in_backup = data_path_in_backup;
351	
352	    if (partitions)
353	    {
354	        if (!res_table_info.partitions)
355	            res_table_info.partitions.emplace();
356	        insertAtEnd(*res_table_info.partitions, *partitions);
357	    }
358	
359	    /// Special handling for ACL-related system tables.
360	    if (!restore_settings.structure_only && isSystemAccessTableName(table_name))
361	    {
362	        if (!access_restorer)
363	            access_restorer = std::make_unique<AccessRestorerFromBackup>(backup, restore_settings);
364	
365	        try
366	        {
367	            /// addDataPath() will parse access*.txt files and extract access entities from them.
368	            /// We need to do that early because we need those access entities to check access.
369	            access_restorer->addDataPath(data_path_in_backup);
370	        }
371	        catch (Exception & e)
372	        {
373	            e.addMessage("While parsing data of {} from backup", tableNameWithTypeToString(table_name.database, table_name.table, false));
374	            throw;
375	        }
376	    }
377	}
