379	void RestorerFromBackup::findDatabaseInBackup(const String & database_name_in_backup, const std::set<DatabaseAndTableName> & except_table_names)
380	{
381	    std::optional<fs::path> metadata_path;
382	    std::unordered_set<String> table_names_in_backup;
383	    for (const auto & root_path_in_backup : root_paths_in_backup)
384	    {
385	        fs::path try_metadata_path, try_tables_metadata_path;
386	        if (database_name_in_backup == DatabaseCatalog::TEMPORARY_DATABASE)
387	        {
388	            try_tables_metadata_path = root_path_in_backup / "temporary_tables" / "metadata";
389	        }
390	        else
391	        {
392	            try_metadata_path = root_path_in_backup / "metadata" / (escapeForFileName(database_name_in_backup) + ".sql");
393	            try_tables_metadata_path = root_path_in_backup / "metadata" / escapeForFileName(database_name_in_backup);
394	        }
395	
396	        if (!metadata_path && !try_metadata_path.empty() && backup->fileExists(try_metadata_path))
397	            metadata_path = try_metadata_path;
398	
399	        Strings file_names = backup->listFiles(try_tables_metadata_path);
400	        for (const String & file_name : file_names)
401	        {
402	            if (!file_name.ends_with(".sql"))
403	                continue;
404	            String file_name_without_ext = file_name.substr(0, file_name.length() - strlen(".sql"));
405	            table_names_in_backup.insert(unescapeForFileName(file_name_without_ext));
406	        }
407	    }
408	
409	    if (!metadata_path && table_names_in_backup.empty())
410	        throw Exception(ErrorCodes::BACKUP_ENTRY_NOT_FOUND, "Database {} not found in backup", backQuoteIfNeed(database_name_in_backup));
411	
412	    if (metadata_path)
413	    {
414	        auto read_buffer = backup->readFile(*metadata_path)->getReadBuffer();
415	        String create_query_str;
416	        readStringUntilEOF(create_query_str, *read_buffer);
417	        read_buffer.reset();
418	        ParserCreateQuery create_parser;
419	        ASTPtr create_database_query = parseQuery(create_parser, create_query_str, 0, DBMS_DEFAULT_MAX_PARSER_DEPTH);
420	        renameDatabaseAndTableNameInCreateQuery(create_database_query, renaming_map, context->getGlobalContext());
421	
422	        String database_name = renaming_map.getNewDatabaseName(database_name_in_backup);
423	        DatabaseInfo & database_info = database_infos[database_name];
424	
425	        if (database_info.create_database_query && (serializeAST(*database_info.create_database_query) != serializeAST(*create_database_query)))
426	        {
427	            throw Exception(
428	                ErrorCodes::CANNOT_RESTORE_DATABASE,
429	                "Extracted two different create queries for the same database {}: {} and {}",
430	                backQuoteIfNeed(database_name),
431	                serializeAST(*database_info.create_database_query),
432	                serializeAST(*create_database_query));
433	        }
434	
435	        database_info.create_database_query = create_database_query;
436	        database_info.is_predefined_database = DatabaseCatalog::isPredefinedDatabase(database_name);
437	    }
438	
439	    for (const String & table_name_in_backup : table_names_in_backup)
440	    {
441	        if (except_table_names.contains({database_name_in_backup, table_name_in_backup}))
442	            continue;
443	
444	        findTableInBackup({database_name_in_backup, table_name_in_backup}, /* partitions= */ {});
445	    }
446	}
