448	void RestorerFromBackup::findEverythingInBackup(const std::set<String> & except_database_names, const std::set<DatabaseAndTableName> & except_table_names)
449	{
450	    std::unordered_set<String> database_names_in_backup;
451	
452	    for (const auto & root_path_in_backup : root_paths_in_backup)
453	    {
454	        Strings file_names = backup->listFiles(root_path_in_backup / "metadata");
455	        for (String & file_name : file_names)
456	        {
457	            if (file_name.ends_with(".sql"))
458	                file_name.resize(file_name.length() - strlen(".sql"));
459	            database_names_in_backup.emplace(unescapeForFileName(file_name));
460	        }
461	
462	        if (backup->hasFiles(root_path_in_backup / "temporary_tables" / "metadata"))
463	            database_names_in_backup.emplace(DatabaseCatalog::TEMPORARY_DATABASE);
464	    }
465	
466	    for (const String & database_name_in_backup : database_names_in_backup)
467	    {
468	        if (except_database_names.contains(database_name_in_backup))
469	            continue;
470	
471	        findDatabaseInBackup(database_name_in_backup, except_table_names);
472	    }
473	}
