475	void RestorerFromBackup::checkAccessForObjectsFoundInBackup() const
476	{
477	    AccessRightsElements required_access;
478	    for (const auto & [database_name, database_info] : database_infos)
479	    {
480	        if (database_info.is_predefined_database)
481	            continue;
482	
483	        AccessFlags flags;
484	
485	        if (restore_settings.create_database != RestoreDatabaseCreationMode::kMustExist)
486	            flags |= AccessType::CREATE_DATABASE;
487	
488	        if (!flags)
489	            flags = AccessType::SHOW_DATABASES;
490	
491	        required_access.emplace_back(flags, database_name);
492	    }
493	
494	    for (const auto & [table_name, table_info] : table_infos)
495	    {
496	        if (table_info.is_predefined_table)
497	        {
498	            if (isSystemFunctionsTableName(table_name))
499	            {
500	                /// CREATE_FUNCTION privilege is required to restore the "system.functions" table.
501	                if (!restore_settings.structure_only && table_info.has_data)
502	                    required_access.emplace_back(AccessType::CREATE_FUNCTION);
503	            }
504	            /// Privileges required to restore ACL system tables are checked separately
505	            /// (see access_restore_task->getRequiredAccess() below).
506	            continue;
507	        }
508	
509	        if (table_name.database == DatabaseCatalog::TEMPORARY_DATABASE)
510	        {
511	            if (restore_settings.create_table != RestoreTableCreationMode::kMustExist)
512	                required_access.emplace_back(AccessType::CREATE_TEMPORARY_TABLE);
513	            continue;
514	        }
515	
516	        AccessFlags flags;
517	        const ASTCreateQuery & create = table_info.create_table_query->as<const ASTCreateQuery &>();
518	
519	        if (restore_settings.create_table != RestoreTableCreationMode::kMustExist)
520	        {
521	            if (create.is_dictionary)
522	                flags |= AccessType::CREATE_DICTIONARY;
523	            else if (create.is_ordinary_view || create.is_materialized_view || create.is_live_view)
524	                flags |= AccessType::CREATE_VIEW;
525	            else
526	                flags |= AccessType::CREATE_TABLE;
527	        }
528	
529	        if (!restore_settings.structure_only && table_info.has_data)
530	        {
531	            flags |= AccessType::INSERT;
532	        }
533	
534	        if (!flags)
535	        {
536	            if (create.is_dictionary)
537	                flags = AccessType::SHOW_DICTIONARIES;
538	            else
539	                flags = AccessType::SHOW_TABLES;
540	        }
541	
542	        required_access.emplace_back(flags, table_name.database, table_name.table);
543	    }
544	
545	    if (access_restorer)
546	        insertAtEnd(required_access, access_restorer->getRequiredAccess());
547	
548	    /// We convert to AccessRights and back to check access rights in a predictable way
549	    /// (some elements could be duplicated or not sorted).
550	    required_access = AccessRights{required_access}.getElements();
551	
552	    context->checkAccess(required_access);
553	}
