564	void RestorerFromBackup::createDatabase(const String & database_name) const
565	{
566	    if (restore_settings.create_database == RestoreDatabaseCreationMode::kMustExist)
567	        return;
568	
569	    /// Predefined databases always exist.
570	    const auto & database_info = database_infos.at(database_name);
571	    if (database_info.is_predefined_database)
572	        return;
573	
574	    auto create_database_query = database_info.create_database_query;
575	    if (restore_settings.create_table == RestoreTableCreationMode::kCreateIfNotExists)
576	    {
577	        create_database_query = create_database_query->clone();
578	        create_database_query->as<ASTCreateQuery &>().if_not_exists = true;
579	    }
580	
581	    LOG_TRACE(log, "Creating database {}: {}", backQuoteIfNeed(database_name), serializeAST(*create_database_query));
582	
583	    try
584	    {
585	        /// Execute CREATE DATABASE query.
586	        InterpreterCreateQuery interpreter{create_database_query, context};
587	        interpreter.setInternal(true);
588	        interpreter.execute();
589	    }
590	    catch (Exception & e)
591	    {
592	        e.addMessage("While creating database {}", backQuoteIfNeed(database_name));
593	        throw;
594	    }
595	}
