597	void RestorerFromBackup::checkDatabase(const String & database_name)
598	{
599	    auto & database_info = database_infos.at(database_name);
600	    try
601	    {
602	        DatabasePtr database = DatabaseCatalog::instance().getDatabase(database_name);
603	        database_info.database = database;
604	
605	        if (!restore_settings.allow_different_database_def && !database_info.is_predefined_database)
606	        {
607	            /// Check that the database's definition is the same as expected.
608	            ASTPtr create_database_query = database->getCreateDatabaseQuery();
609	            adjustCreateQueryForBackup(create_database_query, context->getGlobalContext(), nullptr);
610	            ASTPtr expected_create_query = database_info.create_database_query;
611	            if (serializeAST(*create_database_query) != serializeAST(*expected_create_query))
612	            {
613	                throw Exception(
614	                    ErrorCodes::CANNOT_RESTORE_DATABASE,
615	                    "The database has a different definition: {} "
616	                    "comparing to its definition in the backup: {}",
617	                    serializeAST(*create_database_query),
618	                    serializeAST(*expected_create_query));
619	            }
620	        }
621	    }
622	    catch (Exception & e)
623	    {
624	        e.addMessage("While checking database {}", backQuoteIfNeed(database_name));
625	        throw;
626	    }
627	}
