629	void RestorerFromBackup::createTables()
630	{
631	    while (true)
632	    {
633	        /// We need to create tables considering their dependencies.
634	        auto tables_to_create = findTablesWithoutDependencies();
635	        if (tables_to_create.empty())
636	            break; /// We've already created all the tables.
637	
638	        for (const auto & table_name : tables_to_create)
639	        {
640	            createTable(table_name);
641	            checkTable(table_name);
642	            insertDataToTable(table_name);
643	        }
644	    }
645	}
