647	void RestorerFromBackup::createTable(const QualifiedTableName & table_name)
648	{
649	    if (restore_settings.create_table == RestoreTableCreationMode::kMustExist)
650	        return;
651	
652	    /// Predefined tables always exist.
653	    auto & table_info = table_infos.at(table_name);
654	    if (table_info.is_predefined_table)
655	        return;
656	
657	    auto create_table_query = table_info.create_table_query;
658	    if (restore_settings.create_table == RestoreTableCreationMode::kCreateIfNotExists)
659	    {
660	        create_table_query = create_table_query->clone();
661	        create_table_query->as<ASTCreateQuery &>().if_not_exists = true;
662	    }
663	
664	    LOG_TRACE(
665	        log, "Creating {}: {}", tableNameWithTypeToString(table_name.database, table_name.table, false), serializeAST(*create_table_query));
666	
667	    try
668	    {
669	        DatabasePtr database = DatabaseCatalog::instance().getDatabase(table_name.database);
670	        table_info.database = database;
671	
672	        /// Execute CREATE TABLE query (we call IDatabase::createTableRestoredFromBackup() to allow the database to do some
673	        /// database-specific things).
674	        database->createTableRestoredFromBackup(
675	            create_table_query,
676	            context,
677	            restore_coordination,
678	            std::chrono::duration_cast<std::chrono::milliseconds>(create_table_timeout).count());
679	    }
680	    catch (Exception & e)
681	    {
682	        e.addMessage("While creating {}", tableNameWithTypeToString(table_name.database, table_name.table, false));
683	        throw;
684	    }
685	}
