687	void RestorerFromBackup::checkTable(const QualifiedTableName & table_name)
688	{
689	    auto & table_info = table_infos.at(table_name);
690	    auto database = table_info.database;
691	
692	    try
693	    {
694	        if (!database)
695	        {
696	            database = DatabaseCatalog::instance().getDatabase(table_name.database);
697	            table_info.database = database;
698	        }
699	
700	        auto resolved_id = (table_name.database == DatabaseCatalog::TEMPORARY_DATABASE)
701	            ? context->resolveStorageID(StorageID{"", table_name.table}, Context::ResolveExternal)
702	            : context->resolveStorageID(StorageID{table_name.database, table_name.table}, Context::ResolveGlobal);
703	
704	        StoragePtr storage = database->getTable(resolved_id.table_name, context);
705	        table_info.storage = storage;
706	        table_info.table_lock = storage->lockForShare(context->getInitialQueryId(), context->getSettingsRef().lock_acquire_timeout);
707	
708	        if (!restore_settings.allow_different_table_def && !table_info.is_predefined_table)
709	        {
710	            ASTPtr create_table_query = database->getCreateTableQuery(resolved_id.table_name, context);
711	            adjustCreateQueryForBackup(create_table_query, context->getGlobalContext(), nullptr);
712	            ASTPtr expected_create_query = table_info.create_table_query;
713	            if (serializeAST(*create_table_query) != serializeAST(*expected_create_query))
714	            {
715	                throw Exception(
716	                    ErrorCodes::CANNOT_RESTORE_TABLE,
717	                    "The table has a different definition: {} "
718	                    "comparing to its definition in the backup: {}",
719	                    serializeAST(*create_table_query),
720	                    serializeAST(*expected_create_query));
721	            }
722	        }
723	    }
724	    catch (Exception & e)
725	    {
726	        e.addMessage("While checking {}", tableNameWithTypeToString(table_name.database, table_name.table, false));
727	        throw;
728	    }
729	}
