731	void RestorerFromBackup::insertDataToTable(const QualifiedTableName & table_name)
732	{
733	    if (restore_settings.structure_only)
734	        return;
735	
736	    auto & table_info = table_infos.at(table_name);
737	    auto storage = table_info.storage;
738	
739	    try
740	    {
741	        const auto & data_path_in_backup = table_info.data_path_in_backup;
742	        const auto & partitions = table_info.partitions;
743	        if (partitions && !storage->supportsBackupPartition())
744	        {
745	            throw Exception(
746	                ErrorCodes::CANNOT_RESTORE_TABLE,
747	                "Table engine {} doesn't support partitions",
748	                storage->getName());
749	        }
750	        storage->restoreDataFromBackup(*this, data_path_in_backup, partitions);
751	    }
752	    catch (Exception & e)
753	    {
754	        e.addMessage("While restoring data of {}", tableNameWithTypeToString(table_name.database, table_name.table, false));
755	        throw;
756	    }
757	}
