759	/// Returns the list of tables without dependencies or those which dependencies have been created before.
760	std::vector<QualifiedTableName> RestorerFromBackup::findTablesWithoutDependencies() const
761	{
762	    std::vector<QualifiedTableName> tables_without_dependencies;
763	    bool all_tables_created = true;
764	
765	    for (const auto & [key, table_info] : table_infos)
766	    {
767	        if (table_info.storage)
768	            continue;
769	
770	        /// Found a table which is not created yet.
771	        all_tables_created = false;
772	
773	        /// Check if all dependencies have been created before.
774	        bool all_dependencies_met = true;
775	        for (const auto & dependency : table_info.dependencies)
776	        {
777	            auto it = table_infos.find(dependency);
778	            if ((it != table_infos.end()) && !it->second.storage)
779	            {
780	                all_dependencies_met = false;
781	                break;
782	            }
783	        }
784	
785	        if (all_dependencies_met)
786	            tables_without_dependencies.push_back(key);
787	    }
788	
789	    if (!tables_without_dependencies.empty())
790	        return tables_without_dependencies;
791	
792	    if (all_tables_created)
793	        return {};
794	
795	    /// Cyclic dependency? We'll try to create those tables anyway but probably it's going to fail.
796	    std::vector<QualifiedTableName> tables_with_cyclic_dependencies;
797	    for (const auto & [key, table_info] : table_infos)
798	    {
799	        if (!table_info.storage)
800	            tables_with_cyclic_dependencies.push_back(key);
801	    }
802	
803	    /// Only show a warning here, proper exception will be thrown later on creating those tables.
804	    LOG_WARNING(
805	        log,
806	        "Some tables have cyclic dependency from each other: {}",
807	        boost::algorithm::join(
808	            tables_with_cyclic_dependencies
809	                | boost::adaptors::transformed([](const QualifiedTableName & table_name) -> String { return table_name.getFullName(); }),
810	            ", "));
811	
812	    return tables_with_cyclic_dependencies;
813	}
