829	RestorerFromBackup::DataRestoreTasks RestorerFromBackup::getDataRestoreTasks()
830	{
831	    if (data_restore_tasks.empty())
832	        return {};
833	
834	    LOG_TRACE(log, "Will insert data to tables");
835	
836	    /// Storages and table locks must exist while we're executing data restoring tasks.
837	    auto storages = std::make_shared<std::vector<StoragePtr>>();
838	    auto table_locks = std::make_shared<std::vector<TableLockHolder>>();
839	    storages->reserve(table_infos.size());
840	    table_locks->reserve(table_infos.size());
841	    for (const auto & table_info : table_infos | boost::adaptors::map_values)
842	    {
843	        storages->push_back(table_info.storage);
844	        table_locks->push_back(table_info.table_lock);
845	    }
846	
847	    DataRestoreTasks res_tasks;
848	    for (const auto & task : data_restore_tasks)
849	        res_tasks.push_back([task, storages, table_locks] { task(); });
850	
851	    return res_tasks;
852	}
